import "server-only";
import fs from "node:fs";
import path from "node:path";
import type { BankCounts, Difficulty, Question } from "./types";
import type { SectionId } from "./taxonomy";

// Live question bank, generated by `npm run bank:build` (runs automatically before dev/build).
const DIST = path.join(process.cwd(), "content", "bank", "dist");

let questions: Question[] | null = null;
function all(): Question[] {
  questions ??= JSON.parse(fs.readFileSync(path.join(DIST, "questions.json"), "utf8")) as Question[];
  return questions;
}

export function getCounts(): BankCounts {
  return JSON.parse(fs.readFileSync(path.join(DIST, "counts.json"), "utf8")) as BankCounts;
}

export interface QuestionQuery {
  section: SectionId;
  domain: string | "all";
  difficulty: Difficulty | "all";
  limit: number;
  exclude?: Set<string>;
}

/** Random sample of matching questions (prefers ones not in `exclude`). */
export function sampleQuestions({ section, domain, difficulty, limit, exclude }: QuestionQuery): Question[] {
  const pool = all().filter(
    (q) => q.section === section && (domain === "all" || q.domain === domain) && (difficulty === "all" || q.difficulty === difficulty),
  );
  const fresh = exclude?.size ? pool.filter((q) => !exclude.has(q.id)) : pool;
  const picked = take(fresh, limit);
  // Top up with already-seen questions only when the fresh pool runs out.
  if (picked.length < limit && fresh.length < pool.length) {
    picked.push(...take(pool.filter((q) => exclude!.has(q.id)), limit - picked.length));
  }
  return picked;
}

/** Up to n random items (partial Fisher–Yates). */
function take<T>(list: T[], n: number): T[] {
  const a = [...list];
  const count = Math.min(n, a.length);
  for (let i = 0; i < count; i++) {
    const j = i + Math.floor(Math.random() * (a.length - i));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a.slice(0, count);
}
